'use strict';
const host=document.querySelector('#works'),message=document.querySelector('#message');
fetch('/api/public/showcase').then(async response=>{if(!response.ok)throw Error('作品展暂时无法加载');return response.json();}).then(rows=>{if(!rows.length){message.textContent='作品正在准备中，欢迎稍后再来看。';return;}for(const row of rows){const card=document.createElement('article');card.className='card work-card';const type=document.createElement('span');type.className='eyebrow';type.textContent=row.program_title;card.append(type);const title=document.createElement('h3');title.textContent=row.lesson_title;card.append(title);const maker=document.createElement('p');maker.className='muted';maker.textContent='创作者编号 · '+row.code;card.append(maker);const link=document.createElement('a');link.className='button';link.href=row.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='打开作品 ↗';card.append(link);host.append(card);}}).catch(error=>message.textContent=error.message);
